css:
@page {
	size: 80mm auto;
	margin: 0;
}

* {
	box-sizing: border-box;
	-webkit-print-color-adjust: exact;
	print-color-adjust: exact;
}

body {
	font-family: Arial, Helvetica, sans-serif;
	font-size: 11px;
	font-weight: 600;
	line-height: 1.45;
	margin: 0;
	padding: 5mm 4mm;
	color: #000;
	background: #fff;
	width: 72mm;
}

.receipt {
	width: 100%;
	margin: 0 auto;
}

/* ----------------------------------------------------
   HEADER
---------------------------------------------------- */

.header,
.center {
	text-align: center;
	margin-bottom: 8px;
}

.company-name,
.center h2 {
	margin: 0;
	font-size: 18px;
	font-weight: 700;
	line-height: 1.15;
	text-transform: uppercase;
	letter-spacing: .2px;
}

.company-location,
.center .small {
	margin-top: 3px;
	font-size: 10px;
	font-weight: 600;
	line-height: 1.4;
	color: #444;
}

.report-title,
.center h3 {
	margin: 8px 0 5px;
	font-size: 14px;
	font-weight: 700;
	text-transform: uppercase;
	letter-spacing: .5px;
}

.report-info {
	margin-top: 5px;
	font-size: 10px;
	line-height: 1.5;
}

/* ----------------------------------------------------
   DIVIDER
---------------------------------------------------- */

hr,
.divider {
	border-top: 2px solid #000;
	margin: 8px 0;
}

/* ----------------------------------------------------
   SECTIONS
---------------------------------------------------- */

.section {
	margin: 12px 0;
}

.section-title {
	font-size: 11px;
	font-weight: bold;
	margin: 8px 0 6px 0;
	border-bottom: 1px solid #000;
	padding-bottom: 3px;
	text-transform: uppercase;
}

/* ----------------------------------------------------
   TABLES
---------------------------------------------------- */

table {
	width: 100%;
	border-collapse: collapse;
	margin-top: 6px;
	font-size: 10px;
}

thead th {
	padding: 5px 0;
	font-size: 10px;
	font-weight: 700;
	text-transform: uppercase;
	text-align: left;
	border-bottom: 1px solid #000;
}

tbody td {
	padding: 5px 0 !important;
	font-size: 10px;
	border-bottom: 1px dotted #b5b5b5;
	vertical-align: top;
}

tfoot td {
	padding: 6px 0 !important;
	font-size: 10px;
}

th,
td {
	font-weight: 600;
}

td:first-child {
	padding-right: 10px;
}

td:last-child {
	white-space: nowrap;
}

/* ----------------------------------------------------
   ALIGNMENTS
---------------------------------------------------- */

.right,
.text-right,
.payment-amount,
.summary-value,
.item-amount {
	text-align: right;
}

.left,
.text-left {
	text-align: left;
}

.center,
.text-center {
	text-align: center;
}

/* ----------------------------------------------------
   PAYMENT TABLE
---------------------------------------------------- */

.payment-table .payment-type {
	width: 48%;
}

.payment-table .payment-amount {
	width: 17%;
}

/* ----------------------------------------------------
   SUMMARY TABLE
---------------------------------------------------- */

.summary-table {
	width: 100%;
	border-collapse: collapse;
	margin: 6px 0;
	font-size: 10px;
}

.summary-table td {
	border: none;
	padding: 2px 0 !important;
	font-size: 10px;
	font-weight: bold;
}

.summary-label {
	width: 60%;
	font-weight: bold;
}

.summary-value {
	width: 40%;
	text-align: right;
	font-weight: bold;
}
/* ----------------------------------------------------
   ITEM TABLE
---------------------------------------------------- */

.items-table .item-name {
	width: 52%;
}

.items-table .item-qty {
	width: 18%;
	text-align: center;
}

.items-table .item-amount {
	width: 30%;
}

/* ----------------------------------------------------
   TOTAL ROWS
---------------------------------------------------- */

.total,
.total-row {
	font-weight: 700;
}

.total td,
.total-row td {
	padding: 7px 0;
	border-top: 1px solid #000;
	border-bottom: 1px solid #000;
	background: #f5f5f5;
	font-size: 11px;
	font-weight: 700;
}

/* ----------------------------------------------------
   RETURNS
---------------------------------------------------- */

.returns-section {
	padding-left: 8px;
	border-left: 3px solid #d32f2f;
}

.returns-row {
	background: #fff5f5;
}

.returns-amount {
	color: #d32f2f;
	font-weight: 700;
}

/* ----------------------------------------------------
   SIGNATURE
---------------------------------------------------- */

.signature,
.signature-section {
	margin-top: 28px;
	text-align: center;
}

.signature::before,
.signature-line {
	content: "";
	display: block;
	width: 50mm;
	margin: 0 auto 8px;
	border-top: 2px solid #000;
}

.signature-label {
	font-size: 10px;
	font-weight: 700;
	text-transform: uppercase;
}

/* ----------------------------------------------------
   FOOTER
---------------------------------------------------- */

.footer {
	margin-top: 10px;
	text-align: center;
	font-size: 9px;
	font-weight: bold;
}

/* ----------------------------------------------------
   HELPERS
---------------------------------------------------- */

.small {
	font-size: 9px;
}

.bold {
	font-weight: 700;
}

table tr:first-child td {
	padding-top: 2px;
}

table tr:last-child td {
	padding-bottom: 2px;
}

h2,
h3,
h4 {
	line-height: 1.2;
}
